SEKSAUN = {'KazuFatin': ['enderesu_fatin', 'rai_luan', 'rai_luan_unidade', 'poligon', 'poligon_luan_m2', 'poligon_keliling_m'], 'KazuEntidade': ['projetu', 'entidade_foti', 'entidade_kategoria', 'entidade_kategoria_seluk'], 'KazuPopulasaun': ['iha_dadus_uma_kain', 'fonte_dadus_uma_kain', 'observasaun_afetadu'], 'KazuEviksaun': ['eviksaun_akontese', 'data_eviksaun', 'konsultasaun_molok', 'notifikasaun_klaru', 'uza_forsa', 'observasaun_eviksaun'], 'KazuPortavos': ['portavos_naran', 'portavos_kontaktu', 'portavos_observasaun']}
MAMUK = (None, '', 'M2')          # valór default: la kria liña seksaun mamuk


def muda_ba_seksaun(apps, schema_editor):
	Kazu = apps.get_model('kazu', 'Kazu')
	for model_naran, kampu in SEKSAUN.items():
		Model = apps.get_model('kazu', model_naran)
		foun = []
		for k in Kazu.objects.all().only('id', *kampu).iterator(chunk_size=500):
			valor = {c: getattr(k, c) for c in kampu}
			if all(v in MAMUK for v in valor.values()):
				continue
			foun.append(Model(kazu_id=k.pk, **valor))
		Model.objects.bulk_create(foun, batch_size=500)


def fila_ba_kazu(apps, schema_editor):
	Kazu = apps.get_model('kazu', 'Kazu')
	for model_naran, kampu in SEKSAUN.items():
		Model = apps.get_model('kazu', model_naran)
		for obj in Model.objects.all().iterator(chunk_size=500):
			Kazu.objects.filter(pk=obj.kazu_id).update(**{c: getattr(obj, c) for c in kampu})


